import type { Service, SnapshotRow, StockReportSource } from "./types";
import { error } from "./responses";
import { decodeSnapshotRow, isRecord, isUnits } from "./validation";

type LowStockCommand = {
  op: "lowStock";
  belowUnits: number;
};

function parseCommand(raw: unknown): LowStockCommand | undefined {
  if (!isRecord(raw) || raw.op !== "lowStock" || !isUnits(raw.belowUnits)) return undefined;
  return { op: "lowStock", belowUnits: raw.belowUnits };
}

function decodeSnapshot(raw: unknown): SnapshotRow[] | undefined {
  if (!Array.isArray(raw)) return undefined;
  const seen = new Set<string>();
  const rows: SnapshotRow[] = [];
  for (const rawRow of raw) {
    const row = decodeSnapshotRow(rawRow);
    if (!row || seen.has(row.sku)) return undefined;
    seen.add(row.sku);
    rows.push(row);
  }
  return rows;
}

export function createStockReport({ source }: { source: StockReportSource }): Service {
  return {
    async handle(raw) {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        const snapshot = decodeSnapshot(await source.readSnapshot());
        if (!snapshot) return error(500, "storage_unavailable");
        const items = snapshot
          .map((row) => ({ sku: row.sku, availableUnits: row.totalUnits - row.reservedUnits }))
          .filter((item) => item.availableUnits < command.belowUnits)
          .sort((left, right) => left.sku < right.sku ? -1 : left.sku > right.sku ? 1 : 0);
        return { status: 200, body: { items } };
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

